Use ASP.NET Core's **`WebApplicationFactory<T>`** — it creates an in-memory test server and gives you an `HttpClient` wired to it. You can then send real MCP JSON-RPC requests over HTTP without binding to a port.

**1. Add test project dependencies:**

```xml
<PackageReference Include="Microsoft.AspNetCore.Mvc.Testing" Version="9.*" />
<PackageReference Include="xunit" Version="2.*" />
```

**2. Write an integration test:**

```csharp
using System.Net.Http.Json;
using Microsoft.AspNetCore.Mvc.Testing;
using Xunit;

public class McpIntegrationTests
    : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly HttpClient _client;

    public McpIntegrationTests(WebApplicationFactory<Program> factory)
    {
        _client = factory.CreateClient();
    }

    [Fact]
    public async Task Initialize_ReturnsServerCapabilities()
    {
        var request = new
        {
            jsonrpc = "2.0",
            id = 1,
            method = "initialize",
            @params = new
            {
                protocolVersion = "2025-03-26",
                capabilities = new { },
                clientInfo = new { name = "test-client", version = "1.0" }
            }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal("2.0", body.GetProperty("jsonrpc").GetString());
        Assert.Equal(1, body.GetProperty("id").GetInt32());
        Assert.True(body.GetProperty("result").TryGetProperty("capabilities", out _));
    }

    [Fact]
    public async Task ToolsCall_ExecutesTool()
    {
        // Send initialize first, then call a tool
        await InitializeSession();

        var request = new
        {
            jsonrpc = "2.0",
            id = 2,
            method = "tools/call",
            @params = new
            {
                name = "my-tool",
                arguments = new { input = "hello" }
            }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        var content = body.GetProperty("result").GetProperty("content");
        Assert.True(content.GetArrayLength() > 0);
    }
}
```

**Key points:**

- **`WebApplicationFactory<Program>`** boots your real `Program` / `Startup` in-process — middleware, DI, routing all run as normal.
- Replace `/mcp` with whatever your MCP endpoint path is.
- Use `factory.WithWebHostBuilder(b => ...)` to swap dependencies (e.g., inject a mock database) without changing production code.
- For **SSE (Streamable HTTP)** responses, read the stream with `HttpCompletionOption.ResponseHeadersRead` and parse `text/event-stream` lines incrementally.
- Ensure `Program` is accessible to the test project (add `InternalsVisibleTo` or a partial class).

This gives you full protocol-level coverage with zero network overhead.
